<script setup>import {ref,onMounted} from 'vue';import {api,useSession,toast,labels} from '../core';import State from '../components/State.vue';const session=useSession(),data=ref({pets:[],applications:[]}),tab=ref('applied'),loading=ref(false),error=ref(''),busy=ref('');async function load(){loading.value=true;error.value='';try{data.value=await api('/adoptions')}catch(e){error.value=e.message}finally{loading.value=false}}async function act(app,action){busy.value=app.id;try{await api('/adoptions/'+app.id+'/'+action,'POST');toast(action==='failure'?'本轮交接已结束，宠物恢复待领养':'操作已保存');await load()}catch(e){toast(e.message,true)}finally{busy.value=''}}onMounted(load);</script><template><section class="shell section"><div class="section-heading"><div><p class="eyebrow">YOUR ADOPTION JOURNEY</p><h1>我的领养旅程</h1><p>每一步认真，都是对生命的负责。</p></div><RouterLink to="/pets/new" class="btn">发布领养信息 ＋</RouterLink></div><div class="tabs"><button :class="{active:tab==='applied'}" @click="tab='applied'">我申请的</button><button :class="{active:tab==='published'}" @click="tab='published'">我发布的</button></div><State :loading="loading" :error="error" @retry="load"/><template v-if="!loading&&!error"><div v-if="tab==='published'&&!data.pets.length" class="state">还没有发布领养信息</div><div v-if="tab==='published'" class="mini-grid"><RouterLink v-for="p in data.pets" :key="p.id" :to="'/pets/'+p.id" class="mini-pet"><img :src="p.image" :alt="p.name"><div><h3>{{p.name}}</h3><span class="badge">{{labels[p.status]}}</span></div></RouterLink></div><div class="record-list"><article v-for="a in data.applications.filter(a=>tab==='applied'?a.applicantId===session.user?.id:a.publisherId===session.user?.id)" :key="a.id" class="record panel"><RouterLink :to="'/pets/'+a.petId"><img :src="a.image" :alt="a.petName"></RouterLink><div class="record-main"><RouterLink :to="'/pets/'+a.petId"><h3>{{a.petName}}</h3></RouterLink><p>申请人：{{a.applicantName}}</p><span class="badge">{{labels[a.status]}}</span><p v-if="a.status==='SELECTED'" class="hint">发布者{{a.publisherConfirmed?'已':'未'}}确认 · 申请人{{a.applicantConfirmed?'已':'未'}}确认</p></div><div class="record-actions"><button v-if="a.status==='PENDING'&&a.publisherId===session.user?.id" class="btn small" :disabled="!!busy" @click="act(a,'select')">选定申请</button><template v-if="a.status==='SELECTED'"><button class="btn small" :disabled="!!busy" @click="act(a,'success')">确认交接成功</button><button class="btn secondary small" :disabled="!!busy" @click="act(a,'failure')">交接失败，结束本轮</button></template></div></article><div v-if="!data.applications.some(a=>tab==='applied'?a.applicantId===session.user?.id:a.publisherId===session.user?.id)" class="state">这里还没有申请记录</div></div></template></section></template>
